VALUES ('visitor_services', 'services', 'Our Programs & Get Help', 'published', '{"title":"Our Programs & Get Help","seo":{"description":"Find food, free healthcare, employment help and family support. See how to access each service before you visit."},"intro":"Find food, free healthcare, employment help and family support. See how to access each service before you visit.","blocks":[{"id":"help-hero","type":"hero","variant":"plain","eyebrow":"MY Project USA · Columbus, Ohio","heading":"Support starts here.","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the help you need, see what to bring, and know whether to walk in, request an appointment or contact the team."}]}]},"buttons":[{"label":"Call for Help Finding a Service","href":"tel:6149050977","style":"primary"},{"label":"Browse All Programs","href":"/services#section-program-directory","style":"secondary"}]},{"id":"help-jumps","type":"buttons","buttons":[{"label":"Groceries","href":"#option-get-help-0","style":"secondary"},{"label":"Healthcare","href":"#option-get-help-1","style":"secondary"},{"label":"Hot Meals","href":"#option-get-help-2","style":"secondary"},{"label":"Jobs & English","href":"#option-get-help-3","style":"secondary"},{"label":"Youth & Families","href":"#option-get-help-4","style":"secondary"},{"label":"Household Items","href":"#option-get-help-5","style":"secondary"}],"align":"center"},{"id":"get-help","type":"options","heading":"What do you need help with?","showFullText":true,"columns":2,"items":[{"eyebrow":"Walk in · Free groceries","title":"MY Family Pantry & Mid-Ohio Market","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Free groceries and fresh food for neighbors and families facing food insecurity."}]},{"type":"paragraph","content":[{"type":"text","text":"How to get help: walk in during distribution hours. Bring your ID on your first visit to register. No online application is needed."}]},{"type":"paragraph","content":[{"type":"text","text":"Hours: Tuesday, Thursday and Saturday, 10 AM–2 PM; Wednesday, 3–7 PM. Check with the pantry about holiday changes."}]},{"type":"paragraph","content":[{"type":"text","text":"Where: Hilltop Youth Empowerment Center, 3275 Sullivant Ave., Columbus, OH 43204."}]}]},"buttons":[{"label":"Plan Your First Pantry Visit","href":"/services#option-get-help-0","style":"primary"},{"label":"Call the Pantry","href":"tel:6148867849","style":"link"}]},{"eyebrow":"Request an appointment · Free healthcare","title":"Hilltop Free Clinic","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Preventive screenings, primary care and health navigation for eligible uninsured adults."}]},{"type":"paragraph","content":[{"type":"text","text":"How to get help: request an appointment. The clinic team will confirm eligibility, a date and the visit location. Sending a request does not book an appointment."}]},{"type":"paragraph","content":[{"type":"text","text":"Clinics run on select Saturdays. Contact the team for the next available session and what to bring. Interpretation is available."}]}]},"buttons":[{"label":"Request a Clinic Appointment","href":"/services#section-clinic-request","style":"primary"},{"label":"Clinic Details & Languages","href":"/free-clinic","style":"link"}]},{"eyebrow":"Walk in · Free meals","title":"The Community Table & MY Soup Kitchen","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Free hot meals for neighbors who need them. This is the meal assistance program; café takeout and catering are separate paid services."}]},{"type":"paragraph","content":[{"type":"text","text":"How to get help: come during meal service. Meals are first come, first served; no online signup is required."}]},{"type":"paragraph","content":[{"type":"text","text":"Published meal hours: Tuesday–Saturday, noon–3 PM, at 3275 Sullivant Ave. Call before travelling to confirm the current schedule."}]}]},"butt